window.createDailyDiscovery=function(api){
  const M=DiscoveryModel,e=api.esc,state=api.getState;
  const dialog=document.createElement('dialog');dialog.className='discovery-reader';dialog.setAttribute('aria-labelledby','discovery-reader-title');document.body.append(dialog);
  let libraryQuery='',libraryDomain='';
  const saved=id=>(state().insights||[]).some(a=>a.id===id);
  const button=(label,action,id,cls='text-button',date='')=>`<button type="button" class="${cls}" data-discovery-action="${action}" data-id="${e(id||'')}" ${date?`data-date="${e(date)}"`:''} ${action==='save'?`aria-pressed="${saved(id)}"`:''}>${label}</button>`;
  function rows(items,history=false){return items.map(item=>{const a=history?item.article:item;return `<article class="discovery-row"><div><span class="discovery-meta">${e(a.domain)} · ${history?e(item.date)+(item.revisit?' · 重温':''):'收藏于 '+e((a.savedAt||'').slice(0,10))}</span><h3>${button(e(a.title),'open',a.id,'discovery-title-button',history?item.date:'')}</h3><p>${e(a.summary)}</p></div><div class="discovery-row-actions">${button('阅读','open',a.id,'text-button',history?item.date:'')}${button(saved(a.id)?'已收藏':'收藏','save',a.id)}</div></article>`;}).join('');}
  function history(){const records=[...(state().dailyReadings||[])].sort((a,b)=>b.date.localeCompare(a.date));return `<p class="discovery-history-note">回看你在工作台遇见过的新领域。${records.length?'共 '+records.length+' 次展示。':''}</p><div>${records.length?rows(records,true):'<div class="discovery-empty"><h3>暂无往期短读</h3><p>这里保留此前浏览过的精选内容。</p><a href="#knowledge" class="button soft">返回知识典藏</a></div>'}</div>`;}
  function libraryResults(){const items=(state().insights||[]).filter(a=>(!libraryDomain||a.domain===libraryDomain)&&[a.title,a.domain,a.concept,a.summary,...a.body].join(' ').toLowerCase().includes(libraryQuery.toLowerCase())).sort((a,b)=>(a.savedAt||'').localeCompare(b.savedAt||'')*-1);return `<p class="discovery-history-note">${items.length} 篇收藏 · 最近收藏优先</p>${items.length?rows(items):'<div class="discovery-empty"><h3>把值得重读的视角留下来</h3><p>在「每日一隅」点收藏，就能在这里重新找到它。</p><a href="#discover" class="text-button">浏览往期精选 →</a></div>'}`;}
  function library(){return `<section id="discovery-library"><div class="discovery-library-head"><div><h2>知识短读</h2><p>收藏读过的好概念，给思考留下新的入口。</p></div><a href="#discover" class="text-button">往期回看</a></div><div class="discovery-library-filter"><input type="search" id="discovery-search" aria-label="搜索知识短读" placeholder="搜索标题、概念或内容" value="${e(libraryQuery)}"><select id="discovery-domain" aria-label="筛选短读领域"><option value="">全部领域</option>${[...new Set((state().insights||[]).map(a=>a.domain))].map(d=>`<option ${d===libraryDomain?'selected':''}>${e(d)}</option>`).join('')}</select></div><div id="discovery-library-results">${libraryResults()}</div></section>`;}
  function update(){
    const list=document.querySelector('#discovery-library-results');if(list)list.innerHTML=libraryResults();
    const count=document.querySelector('#tab-insights span');if(count)count.textContent=(state().insights||[]).length;
    for(const el of document.querySelectorAll('[data-discovery-action="save"]')){const yes=saved(el.dataset.id);el.textContent=yes?'已收藏':'收藏';el.setAttribute('aria-pressed',String(yes));}
  }
  function open(id,date=''){
    const article=M.find(state(),id);if(!article)return api.toast('这篇内容已不可用');
    if(date&&!(state().dailyReadings||[]).find(r=>r.date===date&&r.article.id===id)?.openedAt)api.commit(next=>{const record=next.dailyReadings?.find(r=>r.date===date&&r.article.id===id);if(record)record.openedAt=new Date().toISOString();});
    dialog.innerHTML=`<div class="dialog-head"><span class="discovery-kicker">每日一隅 · ${e(article.domain)}</span>${button('×','close','','close')}</div><div class="discovery-reader-meta">预置精选 · ${e(article.concept)} · 约 2 分钟</div><h2 id="discovery-reader-title">${e(article.title)}</h2><p class="discovery-reader-lead">${e(article.summary)}</p><div class="discovery-prose">${article.body.map(p=>`<p>${e(p)}</p>`).join('')}<h3>一个例子</h3><p>${e(article.example)}</p><div class="discovery-question"><span>换个角度 · 编辑提问</span><p>${e(article.question)}</p></div></div><div class="discovery-source"><span>来源与延伸阅读 · 核对于 ${e(article.checkedAt)}</span><a href="${e(M.safeUrl(article.url)||'#')}" target="_blank" rel="noopener noreferrer">${e(article.source)}</a><small>中文内容为简要整理，提问与类比用于启发思考。</small></div><div class="discovery-reader-tools">${button(saved(id)?'已收藏':'收藏','save',id,'button soft')}<span>收藏后可在「知识典藏 → 知识短读」找到</span></div><details class="discovery-thought"><summary>记下我的启发 → 灵感拾萃</summary><form><label for="discovery-thought-text">读完后，你想到了什么？</label><textarea id="discovery-thought-text" rows="3" required maxlength="4000" placeholder="写下联想到的事，稍后再整理……"></textarea><p class="error" role="alert"></p><button class="button primary" type="submit">收进灵感拾萃</button></form></details>`;
    dialog.querySelector('form').onsubmit=event=>{event.preventDefault();const field=dialog.querySelector('textarea'),text=field.value.trim();if(!text)return;const ok=api.commit(next=>{next.inbox.unshift({id:api.uid(),text:`${text}\n\n阅读来源：${article.title}\n${article.url}`,sourceInsightId:id,createdAt:new Date().toLocaleString('zh-CN')});});if(ok){field.value='';update();api.toast('想法已收进灵感拾萃');}else dialog.querySelector('.error').textContent='未能保存，输入已保留，请稍后重试。';};
    if(!dialog.open)dialog.showModal();dialog.scrollTop=0;update();
  }
  document.addEventListener('click',event=>{const target=event.target.closest('[data-discovery-action]');if(!target)return;const {discoveryAction:action,id,date}=target.dataset;
    if(action==='close'){dialog.close();return;}if(action==='open'){open(id,date);return;}
    if(action==='save'){const a=M.find(state(),id);if(!a)return;const wasSaved=saved(id);if(api.commit(next=>wasSaved?M.unsave(next,id):M.save(next,a))){update();api.toast(wasSaved?'已取消收藏，往期记录仍保留':'已收藏到知识典藏 · 知识短读');}}
  });
  document.addEventListener('input',event=>{if(event.target.id==='discovery-search'){libraryQuery=event.target.value;update();}});
  document.addEventListener('change',event=>{if(event.target.id==='discovery-domain'){libraryDomain=event.target.value;update();}});
  return {history,library,open};
};
